/* Fictional, browser-local bulk mail preview. No network mail transport. */
(function(root){'use strict';const R=root.Reunion;
function prepare(s){s.broadcasts??=[];}
function admin(s,uid){const u=s.people.find(p=>p.id===uid);if(!u||!['owner','organizer'].includes(u.role))throw new Error('幹事のログインが必要です。');return u;}
function audience(s,target){if(!['all','active'].includes(target))throw new Error('送信対象を選択してください。');const recipients=[],excluded=[],seen=new Set();for(const p of s.people.slice().sort((a,b)=>a.id-b.id)){if(target==='active'&&!R.active(p))continue;const email=String(p.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){excluded.push({id:p.id,reason:'メールアドレス不正'});continue;}if(seen.has(email)){excluded.push({id:p.id,reason:'同じ宛先を1件に集約'});continue;}seen.add(email);recipients.push({id:p.id,name:p.name,email,status:p.status});}return {recipients,excluded};}
function preview(s,d,uid){prepare(s);const u=admin(s,uid),subject=String(d.subject||'').trim(),body=String(d.body||'').trim(),target=d.target||'all';if(!subject||subject.length>200||/[\r\n]/.test(subject)||!body||body.length>10000)throw new Error('件名は改行なし200文字以内、本文は10000文字以内で入力してください。');const a=audience(s,target);if(!a.recipients.length)throw new Error('送信対象がありません。');const b={id:Math.max(0,...s.broadcasts.map(b=>b.id))+1,subject,body,target,audience:a,status:'draft',actor:u.name,created:new Date().toISOString()};s.broadcasts.push(b);R.audit(s,u.name,'一斉メールの確認用下書き','broadcast:'+b.id,null,{count:a.recipients.length,target},'内容と宛先を固定して保存');return b;}
function queue(s,id,confirm,uid){const u=admin(s,uid),b=s.broadcasts.find(b=>b.id===id);if(!b)throw new Error('下書きがありません。');if(b.status==='development')return b;if(b.status!=='draft'||confirm!=='yes')throw new Error('対象人数と内容の確認にチェックしてください。');if(JSON.stringify(audience(s,b.target))!==JSON.stringify(b.audience))throw new Error('申込者情報が変わりました。下書きを作り直して確認してください。');b.status='development';b.audience.recipients.forEach(r=>s.mail.push({id:Math.max(0,...s.mail.map(m=>m.id))+1,to:r.email,subject:b.subject,body:b.body,at:new Date().toISOString(),status:'開発用・未送信',broadcastId:b.id}));R.audit(s,u.name,'一斉メールを登録','broadcast:'+id,{status:'draft'},{status:b.status,count:b.audience.recipients.length},'ブラウザー内のみ・実送信なし');return b;}
function cancel(s,id,reason,uid){const u=admin(s,uid),b=s.broadcasts.find(b=>b.id===id);if(!b||b.status==='cancelled'||!String(reason||'').trim())throw new Error('停止するメールと理由を確認してください。');b.status='cancelled';s.mail.filter(m=>m.broadcastId===id).forEach(m=>m.status='停止済み・未送信');R.audit(s,u.name,'一斉メールを停止','broadcast:'+id,null,{status:b.status},reason);}
const api={prepare,audience,preview,queue,cancel};root.Broadcast=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
